def normalize_name(s):
    return (s or '').strip().lower()

def find_best_song_id(title, artists):
    target_title = normalize_name(title)
    target_artists = [normalize_name(a) for a in artists]

    def score_result(r):
        r_title = normalize_name(r.get('title'))
        r_artists = [normalize_name(a.get('name')) for a in r.get('artists', [])]
        # perfect if title exact
        title_ok = (r_title == target_title)
        overlap = len(set(target_artists) & set(r_artists))
        # if title not exact, demote heavily
        if not title_ok:
            overlap = overlap - 1000
        # prefer more overlap and exact title
        return (overlap, 1 if title_ok else 0)

    queries = [f"{title} {artists[0]}", title] if artists else [title]
    best=None
    best_score=None
    for q in queries:
        page_index=0
        while True:
            res = apis.spotify.search_songs(query=q, page_index=page_index, page_limit=20)
            if not res:
                break
            # pick best among returned
            for r in res:
                sc = score_result(r)
                if best is None or sc > best_score:
                    best = r
                    best_score = sc
            page_index += 1
    if best is None:
